style.css:
@-moz-document domain("youtube.com") {
:root{ --bg-url: url("https://example.com/your.jpg"); }

  html, body, ytd-app, #page-manager {
    background: var(--bg-url) no-repeat center center fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  #content, ytd-page-manager, ytd-browse, ytd-search, ytd-watch-flexy, ytd-app, ytd-masthead, #primary, #secondary {
    background-color: transparent !important;
    background-image: none !important;
  }

  ytd-page-manager, ytd-browse, ytd-watch-flexy, #primary, #secondary {
    background-color: rgba(0,0,0,0.45) !important;
  }

  ytd-masthead, #guide, ytd-guide-renderer {
    background-color: rgba(0,0,0,0.5) !important;
  }

  #player, .html5-video-player, #player-theater-container {
    background-color: transparent !important;
    background-image: none !important;
  }

  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: -1;
  }
}
